using System;

namespace StdbModule;

public static partial class EnglishQuotes
{
    public static class MarcusAurelius
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "The universe is change; our life is what our thoughts make it.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Be not as one that hath ten thousand years to live; death is nigh at hand: while thou livest, while thou hast time, be good.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "I shall meet today inquisitive, ungrateful, violent, treacherous, envious, uncharitable men. All these things have come upon them through ignorance of real good and ill.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "An angry countenance is much against nature...", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "You will find rest from vain fancies if you perform every act in life as though it were your last.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Not to display anger or other emotions. To be free of passion and yet full of love.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Self-control and resistance to distractions. Optimism in adversity—especially illness.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "He was a man who looked at what ought to be done, not to the reputation which is got by a man's acts.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "When you wake up in the morning, tell yourself: The people I deal with today will be meddling, ungrateful, arrogant, dishonest, jealous, and surly. They are like this because they can't tell good from evil.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "We are all made for mutual assistance, as the feet, the hands, and the eyelids, as the rows of the upper and under teeth, from whence it follows that clashing and opposition is perfectly unnatural.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "This that I am, whatever it be, is mere flesh and a little breathe and the ruling Reason", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "All that is from the gods is full of Providence.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "There is a limit to the time assigned you, and if you don't use it to free yourself it will be gone and never return.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Concentrate every minute like a Roman—like a man—on doing what's in front of you with precise and genuine seriousness, tenderly, willingly, with justice. And on freeing yourself from all other distractions.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "You see how few things you have to do to live a satisfying and reverent life? If you can manage this, that's all even the gods can ask of you.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Give thyself time to learn something new and good, and cease to be whirled around.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "You could leave life right now. Let that determine what you do and say and think.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Yet living and dying, honour and dishonour, pain and pleasure, riches and poverty, and so forth are equally the lot of good men and bad. Things like these neither elevate nor degrade; and therefore they are no more good than they are evil.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "The longest-lived and the shortest-lived man, when they come to die, lose one and the same thing.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Remember that all is opinion.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "No state sorrier than that of the man who keeps up a continual round, and pries into \"the secrets of the nether world,\" as saith the poet, and is curious in conjecture of what is in his neighbour's heart.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Though thou be destined to live three thousand years and as many myriads besides, yet remember that no man loseth other life than that which he liveth, nor liveth other than that which he loseth.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "As for life, it is a battle and a sojourning in a strange land; but the fame that comes after is oblivion.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Waste not the remnant of thy life in those imaginations touching other folk, whereby thou contributest not to the common weal.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "The lot assigned to every man is suited to him, and suits him to itself.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "For we carry our fate with us — and it carries us.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Be not unwilling in what thou doest, neither selfish nor unadvised nor obstinate; let not over-refinement deck out thy thought; be not wordy nor a busybody.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "A man should be upright, not kept upright.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "But that which is useful is the better.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Choose what's best.—Best is what benefits me.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Never esteem anything as of advantage to you that will make you break your word or lose your self-respect.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Respect the faculty that forms thy judgments.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Remember that man lives only in the present, in this fleeting instant; all the rest of his life is either past and gone, or not yet revealed.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Each of us lives only now, this brief instant.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "The span we live is small—small as the corner of the earth in which we live it. Small as even the greatest renown, passed from mouth to mouth by short-lived stick figures, ignorant alike of themselves and those long dead.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Nothing has such power to broaden the mind as the ability to investigate systematically and truly all that comes under thy observation in life.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "As surgeons keep their instruments and knives always at hand for cases requiring immediate treatment, so shouldst thou have thy thoughts ready to understand things divine and human, remembering in thy every act, even the smallest, how close is the bond that unites the two.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Nothing earthly succeeds by ignoring heaven, nothing heavenly by ignoring the earth.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "The ruling power within, when it is in its natural state, is so related to outer circumstances that it easily changes to accord with what can be done and what is given it to do.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Let no act be done at haphazard, nor otherwise than according to the finished rules that govern its kind.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "By a tranquil mind I mean nothing else than a mind well ordered.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Men seek retreats for themselves, houses in the country, sea-shores, and mountains; and thou too art wont to desire such things very much. But this is altogether a mark of the most common sort of men, for it is in thy power whenever thou shalt choose to retire into thyself. For nowhere either with more quiet or more freedom from trouble does a man retire than into his own soul.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "The universe is flux, life is opinion.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Think on this doctrine,—that reasoning beings were created for one another's sake; that to be patient is a branch of justice, and that men sin without intending it.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "The abyss of endless time that swallows it all. The emptiness of all those applauding hands. The people who praise us—how capricious they are, how arbitrary. And the tiny region in which it all takes place.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Be straightforward. Look at things like a man, like a human being, like a citizen, like a mortal.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Disturbance comes only from within—from our own perceptions.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "The world is nothing but change. Our life is only perception.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Nothing can come out of nothing, any more than a thing can go back to nothing.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "If mind is common to us, then also the reason, whereby we are reasoning beings, is common. If this be so, then also the reason which enjoins what is to be done or left undone is common. If this be so, law also is common; if this be so, we are citizens; if this be so, we are partakers in one constitution; if this be so, the Universe is a kind of Commonwealth.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Death, like generation, is a secret of Nature.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Choose not to be harmed—and you won't feel harmed. Don't feel harmed—and you haven't been.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "That which makes the man no worse than he was makes his life no worse: it has no power to harm, without or within.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Whatever happens at all happens as it should; you will find this true, if you watch narrowly.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Death,—a stopping of impressions through the senses, and of the pulling of the cords of motion, and of the ways of thought, and of service to the flesh.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Stir up thy mind, and recall thy wits again from thy natural dreams, and visions, and when thou art perfectly awoken, and canst perceive that they were but dreams that troubled thee, as one newly awakened out of another kind of sleep look upon these worldly things with the same mind as thou didst upon those, that thou sawest in thy sleep.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Take heed not to be transformed into a Caesar, not to be dipped in the purple dye, for it does happen. Keep yourself therefore, simple, good, pure, grave, unaffected, the friend of justice, religious, kind, affectionate, strong for your proper work. Wrestle to be the man philosophy wished to make you. Reverence the gods, save men. Life is brief; there is but one harvest of earthly existence, a holy disposition and neighborly acts.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Reverence the gods, and help men. Short is life.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "I consist of a little body and a soul.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Adapt yourself to the environment in which your lot has been cast, and show true love to the fellow-mortals with whom destiny has surrounded you.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "But if we judge only those things which are in our power to be good or bad, there remains no reason either for finding fault with God or standing in a hostile attitude to man.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "The only thing that isn't worthless: to live this life out truthfully and rightly. And be patient with those who don't.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "What is not good for the swarm is not good for the bee.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "How many together with whom I came into the world are already gone out of it.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "I can control my thoughts as necessary; then how can I be troubled?", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Understand however that every man is worth just so much as the things are worth about which he busies himself.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "How many, once lauded in song, are given over to the forgotten; and how many who sung their praises are clean gone long ago!", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Never let the future disturb you. You will meet it, if you have to, with the same weapons of reason which today arm you against the present.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "All things are implicated with one another, and the bond is holy; and there is hardly anything unconnected with any other things. For things have been co-ordinated, and they combine to make up the same universe. For there is one universe made up of all things, and one god who pervades all things, and one substance, and one law, and one reason.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "If you are troubled by external circumstances, it is not the circumstances that trouble you, but your own perception of them - and they are in your power to change at any time.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Whatsoever any man either doth or saith, thou must be good; not for any man's sake, but for thine own nature's sake; as if either gold, or the emerald, or purple, should ever be saying to themselves, Whatsoever any man either doth or saith, I must still be an emerald, and I must keep my colour.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Remember, that to change thy mind upon occasion, and to follow him that is able to rectify thee, is equally ingenuous, as to find out at the first, what is right and just, without help. For of thee nothing is required, that is beyond the extent of thine own deliberation and judgment, and of thine own understanding.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "No matter what anyone says or does, my task is to be good.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "An angry countenance is much against nature, and it is oftentimes the proper countenance of them that are at the point of death. But were it so, that all anger and passion were so thoroughly quenched in thee, that it were altogether impossible to kindle it any more, yet herein must not thou rest satisfied, but further endeavour by good consequence of true ratiocination, perfectly to conceive and understand, that all anger and passion is against reason.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Is any man afraid of change? Why what can take place without change?", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Soon you will have forgotten the world, and soon the world will have forgotten you.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "It is man's peculiar duty to love even those who wrong him.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Nature which governs the whole will soon change all things which thou seest, and out of there substance will make other things, and again other things from the substance of them, in order that the world may ever be new.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Think not so much of what thou hast not as of what thou hast: but of the things which thou hast, select the best, and then reflect how eagerly they would have been sought, if thou hadst them not. At the same time, however, take care that thou dost not, through being so pleased with them, accustom thyself to overvalue them, so as to be disturbed if ever thou shouldst not have them.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Retire into thyself. The rational principle which rules has this nature, that it is content with itself when it does what is<bos>, and so secures tranquility.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Wipe out the imagination. Stop pulling the strings. Confine thyself to the present. ...Divide and distribute every object into the causal [formal] and the material. ...Let the wrong which is done by a man stay there where the wrong was done.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Direct thy attention to what is said. Let thy understanding enter into the things that are doing and the things which do them.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Adorn thyself with simplicity and with indifference towards the things which lie between virtue and vice. Love mankind. Follow God. The poet says that Law rules all. And it is enough to remember that law rules all.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "About fame... Just as the sand-dunes, heaped one upon another, hide each the first, so in life the former deeds are quickly hidden by those that follow after.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "the man who has an elevated mind and takes a view of all time and of all substance, dost thou suppose it possible for him to think that human life is anything great? It is not possible, he said. Such a man then will think that death also is no evil.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "It is royal to do good and be abused.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "It is a base thing for the countenance to be obedient and to regulate and compose itself as the mind commands, and for the mind not to be regulated and composed by itself.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "It is not right to vex ourselves at things, For they care not about it.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "If the gods care not for me and for my children, There is a reason for it.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "For thus it is, men of Athens, in truth: wherever a man has placed himself thinking it is the best place for him, or has been placed by a commander, there in my opinion he ought to stay and to abide the hazard, taking nothing into the reckoning, either death or anything else, before the baseness [of deserting his post].", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Look round at the courses of the stars, as if thou wert going along with them; and constantly consider the changes of the elements into one another; for such thoughts purge away the filth of the terrene life.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Thou mayest foresee... the things which will be. For they will certainly be of like form, and it is not possible that they should deviate from the order of things now: accordingly to have contemplated human life for forty years is the same as to have contemplated it for ten thousand years.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "That which had grown from the earth, to the earth, But that which has sprung from heavenly seed, Back to the heavenly realms returns.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Another may be more expert in casting his opponent; but he is not more social, nor more modest, nor better disciplined to meet all that happens, nor more considerate with respect to the faults of his neighbors.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Where any work can be done conformably to the reason which is common to gods and men, there we have nothing to fear; for where we are able to get profit by means of the activity which is successful and proceeds according to our constitution, there no harm is to be suspected.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Every being ought to do that which is according to its constitution; and all other things have been constituted for the sake of the superior, but the rational for the sake of one another.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Consider thyself to be dead, and to have completed thy life up to the present time; and live according to nature the remainder which is allowed thee.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Love that only which happens to thee and is spun with the thread of thy destiny. For what is more suitable?", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Look within. Within is the fountain of the good, and it will ever bubble up, if thou wilt ever dig.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "The art of life is more like the wrestler's art than the dancer's, in respect of this, that it should stand ready and firm to meet onsets which are sudden and unexpected.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Every soul, the philosopher says, is involuntarily deprived of truth; consequently in the same way it is deprived of justice and temperance and benevolence and everything of the kind. It is most necessary to keep this in mind, for thus thou wilt be more gentle towards all.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Very little is needed to make a happy life.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "To live each day as though one's last, never flustered, never apathetic, never attitudinizing – here is perfection of character.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "The nature of the All moved to make the universe.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "On the occasion of every act ask thyself, How is this with respect to me? Shall I repent of it? A little time and I am dead, and all is gone.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "You may break your heart, but men will still go on as before.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Constantly and, if it be possible, on the occasion of every impression on the soul, apply to it the principles of Physic, of Ethic, and of Dialectic.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "To change your mind and to follow him who sets you right is to be nonetheless the free agent that you were before.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Nature has had regard in everything no less to the end than to the beginning and the continuance, just like a man who throws up a ball. What good is it then for the ball to be thrown up, or harm for it to come down... what good is it to the bubble while it holds together, or what harm when it is burst?", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Short-lived are both the praiser and the praised, and rememberer and the remembered: and all this in a nook of this part of the world; and not even here do all agree, no, not any one with himself: and the whole earth too is a point.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Look to the essence of a thing, whether it be a point of doctrine, of practice, or of interpretation.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Thou sufferest justly: for thou choosest rather to become good to-morrow than to be good to-day.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Remember this, then, that this little compound, thyself, must either be dissolved, or thy poor breath must be extinguished, or be removed and placed elsewhere.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "It is satisfaction to a man to do the proper works of a man.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "There are three relations [between thee and other things]: the one to the body which surrounds thee; the second to the divine cause from which all things come to all; and the third to those who live with thee.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "To accept it without arrogance, to let it go with indifference.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Suppose that thou hast detached thyself from the natural unity... yet here there is this beautiful provision, that it is in thy power again to unite thyself. God has allowed this to no other part, after it has been separated and cut asunder, to come together again. ...he has distinguished man, for he has put it in his power not to be separated at all from the universal ...he has allowed him to be returned and to be united and to resume his place as a part.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Remember that neither the future nor the past pains thee, but only the present. But this is reduced to a very little, if thou only circumscribest it, and chidest thy mind, if it is unable to hold out against even this.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "If thou canst see sharp, look and judge wisely, says the philosopher.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "The things... which are proper to the understanding no other man is used to impede, for neither fire, nor iron, nor tyrant, nor abuse, touches it in any way. When it has been made a sphere, it continues a sphere.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "It is not fit that I should give myself pain, for I have never intentionally given pain even to another.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "If...it be a thing external that causes thy grief, know, that it is not that properly that doth cause it, but thine own conceit and opinion concerning the thing: which thou mayest rid thyself of, when thou wilt.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "External things are not the problem. It's your assessment of them. Which you can erase right now.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "The mind which is free from passions is a citadel, for man has nothing more secure to which he can fly for refuge and for the future be inexpugnable. He then who has not seen this is an ignorant man: but he who has seen it and does not fly to this refuge is unhappy.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "The universal nature has no external space; but the wondrous part of her art is that though she has circumscribed herself, everything which is within her which appears to decay and to grow old and to be useless she changes into herself, and again makes other new things from these very same, so that she requires neither substance from without nor wants a place into which she may cast that which decays. She is content then with her own space, and her own matter, and her own art.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "The cucumber is bitter? Then throw it out. There are brambles in the path? Then go around them. That's all you need to know.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Be not careless in deeds, nor confused in words, nor rambling in thought.", Author = "Marcus Aurelius" },
        };
    }
}